// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Status code.
*
* ## Notes
*
* The status code indicates the following conditions:
*
* -   if equal to zero, then the factorization was successful.
*/
type StatusCode = number;

/**
* Job parameter.
*
* ## Notes
*
* The job parameter can be one of the following:
*
* -   'none': none, return immediately
* -   'permute': permute only
* -   'scale': scale only
* -   'both': both permute and scale
*/
type Job = 'none' | 'permute' | 'scale' | 'both';

/**
* Interface describing `dgebal`.
*/
interface Routine {
	/**
	* Balances a general real matrix `A`.
	*
	* ## Notes
	*
	* The job parameter can be one of the following:
	*
	* -   'none': none, return immediately
	* -   'permute': permute only
	* -   'scale': scale only
	* -   'both': both permute and scale
	*
	* The matrix `A` is overwritten by the balanced matrix. Scale factors are stored in the `scale` array. If `P[ j ]` is the index of the row and column interchanged with row and column j (zero-based) and `D[ j ]` is the scaling factor applied to row and column j, then:
	*
	* -   `scale[ j ]` = `P[ j ]`    for j = `0`,...,`out[ 0 ]-1`
	* -   `scale[ j ]` = `D[ j ]`    for j = `out[ 0 ]`,...,`out[ 1 ]`
	* -   `scale[ j ]` = `P[ j ]`    for j = `out[ 1 ]+1`,...,`N-1`.
	*
	* The order in which the interchanges are made is `N-1` to `out[ 1 ]+1`, then `0` to `out[ 0 ]-1`.
	*
	* @param order - storage layout of `A`
	* @param job - indicates the operations to be performed
	* @param N - number of rows/columns in matrix `A`
	* @param A - input matrix to be balanced
	* @param LDA - leading dimension of `A`
	* @param out - stores the first and last row/column of the balanced submatrix
	* @param scale - array containing permutation and scaling information
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 1.0, 100.0, 0.0, 2.0, 200.0, 0.0, 0.0, 0.0, 3.0 ] );
	* var out = new Int32Array( 2 );
	* var scale = new Float64Array( 3 );
	*
	* dgebal( 'row-major', 'both', 3, A, 3, out, scale );
	* // A => <Float64Array>[ 1, 12.5, 0, 16, 200, 0, 0, 0, 3 ]
	* // out => <Int32Array>[ 0, 1 ]
	* // scale => <Float64Array>[ 8, 1, 2 ]
	*/
	( order: Layout, job: Job, N: number, A: Float64Array, LDA: number, out: Int32Array, scale: Float64Array ): StatusCode;

	/**
	* Balances a general real matrix `A` using alternative indexing semantics.
	*
	* ## Notes
	*
	* The job parameter can be one of the following:
	*
	* -   'none': none, return immediately
	* -   'permute': permute only
	* -   'scale': scale only
	* -   'both': both permute and scale
	*
	* The matrix `A` is overwritten by the balanced matrix. Scale factors are stored in the `scale` array. If `P[ j ]` is the index of the row and column interchanged with row and column j (zero-based) and `D[ j ]` is the scaling factor applied to row and column j, then:
	*
	* -   `scale[ j ]` = `P[ j ]`    for j = `0`,...,`out[ 0 ]-1`
	* -   `scale[ j ]` = `D[ j ]`    for j = `out[ 0 ]`,...,`out[ 1 ]`
	* -   `scale[ j ]` = `P[ j ]`    for j = `out[ 1 ]+1`,...,`N-1`.
	*
	* The order in which the interchanges are made is `N-1` to `out[ 1 ]+1`, then `0` to `out[ 0 ]-1`.
	*
	* @param job - indicates the operations to be performed
	* @param N - number of rows/columns in matrix `A`
	* @param A - input matrix to be balanced
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param out - stores the first and last row/column of the balanced submatrix
	* @param strideOut - stride of `out`
	* @param offsetOut - starting index for `out`
	* @param scale - array containing permutation and scaling information
	* @param strideScale - stride of `scale`
	* @param offsetScale  - starting index for `scale`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 1.0, 100.0, 0.0, 2.0, 200.0, 0.0, 0.0, 0.0, 3.0 ] );
	* var out = new Int32Array( 2 );
	* var scale = new Float64Array( 3 );
	*
	* dgebal.ndarray( 'both', 3, A, 3, 1, 0, out, 1, 0, scale, 1, 0 );
	* // A => <Float64Array>[ 1, 12.5, 0, 16, 200, 0, 0, 0, 3 ]
	* // out => <Int32Array>[ 0, 1 ]
	* // scale => <Float64Array>[ 8, 1, 2 ]
	*/
	ndarray( job: Job, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, out: Int32Array, strideOut: number, offsetOut: number, scale: Float64Array, strideScale: number, offsetScale: number ): StatusCode;
}

/**
* Balances a general real matrix `A`.
*
* ## Notes
*
* The job parameter can be one of the following:
*
* -   'none': none, return immediately
* -   'permute': permute only
* -   'scale': scale only
* -   'both': both permute and scale
*
* The matrix `A` is overwritten by the balanced matrix. Scale factors are stored in the `scale` array. If `P[ j ]` is the index of the row and column interchanged with row and column j (zero-based) and `D[ j ]` is the scaling factor applied to row and column j, then:
*
* -   `scale[ j ]` = `P[ j ]`    for j = `0`,...,`out[ 0 ]-1`
* -   `scale[ j ]` = `D[ j ]`    for j = `out[ 0 ]`,...,`out[ 1 ]`
* -   `scale[ j ]` = `P[ j ]`    for j = `out[ 1 ]+1`,...,`N-1`.
*
* The order in which the interchanges are made is `N-1` to `out[ 1 ]+1`, then `0` to `out[ 0 ]-1`.
*
* @param order - storage layout of `A`
* @param job - indicates the operations to be performed
* @param N - number of rows/columns in matrix `A`
* @param A - input matrix to be balanced
* @param LDA - leading dimension of `A`
* @param out - stores the first and last row/column of the balanced submatrix
* @param scale - array containing permutation and scaling information
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 1.0, 100.0, 0.0, 2.0, 200.0, 0.0, 0.0, 0.0, 3.0 ] );
* var out = new Int32Array( 2 );
* var scale = new Float64Array( 3 );
*
* dgebal( 'row-major', 'both', 3, A, 3, out, scale );
* // A => <Float64Array>[ 1, 12.5, 0, 16, 200, 0, 0, 0, 3 ]
* // out => <Int32Array>[ 0, 1 ]
* // scale => <Float64Array>[ 8, 1, 2 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 1.0, 100.0, 0.0, 2.0, 200.0, 0.0, 0.0, 0.0, 3.0 ] );
* var out = new Int32Array( 2 );
* var scale = new Float64Array( 3 );
*
* dgebal.ndarray( 'both', 3, A, 3, 1, 0, out, 1, 0, scale, 1, 0 );
* // A => <Float64Array>[ 1, 12.5, 0, 16, 200, 0, 0, 0, 3 ]
* // out => <Int32Array>[ 0, 1 ]
* // scale => <Float64Array>[ 8, 1, 2 ]
*/
declare var dgebal: Routine;


// EXPORTS //

export = dgebal;
